// Meeting Planner DS - interactive demo card (Stage 3, repaired).
// Fictional calendar only. Nothing is booked for real and no invitation is sent.

let HOME = 0
let LIST = 1

let events = []       // busy fixtures: {id,title,start,end,time}
let candidates = []   // {start,end,time}
let bookings = {}     // at most ONE slot -> {date,time,tz,attendees}
let sel_idx = 0
let screen = 0
let reviewing = false
let rv_valid = false
let rv_start = 0
let rv_end = 0
let rv_time = ""
let suggestion = ""
let notice = ""
let question = ""
let qstate = ""
let qerr = ""
let qnotice = ""
let answer = ""
let gen = 0
let can_agent = false

let ink = #x1b1b1f
let sub = #x6f6a63
let accent = #x2f5bff
let bg = #xfaf5ec
let panel = #xffffff
let soft = #xefe8db
let good = #x1f7a4d
